<script setup>
import { computed, ref } from "vue";
import { useRouter } from "vue-router";
import DemoSidebar from "../components/DemoSidebar.vue";
import { steecCase } from "../data/demoLearningData";

const router=useRouter();
const step=ref(0);
const maxStep=ref(0);
const labels=ref([null,null,null]);
const thesisChoice=ref(null);
const bridgeChoice=ref(null);
const submitted=ref(false);
const thesisRewrite=ref("");
const evidenceChoice=ref(null);
const trainingChecked=ref(false);
const labelItems=[
  {text:"Whether AI affects learning positively or negatively depends on students themselves.",correct:"T"},
  {text:"Students may skip the process of thinking and organizing their own ideas.",correct:"E"},
  {text:"Therefore, responsible AI use depends on individuals' self-control.",correct:"C"},
];
const labelOptions=["S","T","E","C"];
const recognitionScore=computed(()=>labels.value.reduce((n,x,i)=>n+(x===labelItems[i].correct?1:0),0));
const allDone=computed(()=>labels.value.every(Boolean)&&thesisChoice.value!==null&&bridgeChoice.value!==null);
const functionalScore=computed(()=>(thesisChoice.value===1?1:0)+(bridgeChoice.value===1?1:0));
const outcome=computed(()=>{
  if(recognitionScore.value<2)return "concept";
  if(functionalScore.value<2)return "function";
  return "application";
});
const thesisPassed=computed(()=>{
  const text=thesisRewrite.value.toLowerCase();
  return text.includes("ai") && (text.includes("independent")||text.includes("thinking")||text.includes("depend")||text.includes("overreliance"));
});
const trainingPassed=computed(()=>thesisPassed.value&&evidenceChoice.value===1);
const unlock=(target)=>{maxStep.value=Math.max(maxStep.value,target);step.value=target};
const openStep=(target)=>{if(target<=maxStep.value)step.value=target};
const reset=()=>{step.value=0;maxStep.value=0;labels.value=[null,null,null];thesisChoice.value=null;bridgeChoice.value=null;submitted.value=false;thesisRewrite.value="";evidenceChoice.value=null;trainingChecked.value=false};
</script>

<template><div class="demo-app"><DemoSidebar/><main class="coach-main">
  <header><div><span>AI PERSONAL WRITING COACH</span><h1>STEEC 结构教练</h1></div><div><button :class="{active:false}" @click="router.push('/learning-coach')">案例 A · 语言稳定性</button><button class="active">案例 B · STEEC 结构</button></div></header>
  <section class="case-banner"><div><span>真实匿名案例 · {{steecCase.title}}</span><h2>表面上每一段都有，为什么结构还是失效？</h2><p>系统先判断学生是“不认识结构”，还是“认识标签但不理解功能”，再决定下一步。</p></div><button @click="unlock(1)">开始先备检查 →</button></section>
  <nav class="steps"><button v-for="(name,i) in ['原始作答','先备检查','根因判断','训练处方','专项训练']" :key="name" :disabled="i>maxStep" :class="{active:step===i,done:step>i,locked:i>maxStep}" @click="openStep(i)"><i>{{step>i?'✓':i+1}}</i><span>{{name}}</span></button></nav>
  <section class="work-panel">
    <div v-if="step===0" class="source-grid"><article><span>题目</span><p>{{steecCase.question}}</p><div v-for="s in steecCase.students" :key="s.name"><b>{{s.name}}</b>{{s.text}}</div></article><article><span>学生作答</span><p>{{steecCase.answer}}</p></article></div>
    <div v-else-if="step===1">
      <div class="task-head"><span>PREREQUISITE CHECK</span><h2>你能识别每句话正在承担什么功能吗？</h2><p>先不评价语言，只检查 STEEC 标签与功能理解。</p></div>
      <div class="label-list"><article v-for="(item,i) in labelItems" :key="item.text"><p>{{item.text}}</p><div><button v-for="option in labelOptions" :key="option" :class="{selected:labels[i]===option}" @click="labels[i]=option">{{option}}</button></div></article></div>
      <div class="function-tests"><article><b>哪一个更适合作为核心论点 T？</b><button :class="{selected:thesisChoice===0}" @click="thesisChoice=0">A. Whether AI is beneficial depends on individuals.</button><button :class="{selected:thesisChoice===1}" @click="thesisChoice=1">B. Overreliance on AI may weaken students' independent-thinking ability.</button></article><article><b>论点和例子之间最需要哪条解释桥梁？</b><button :class="{selected:bridgeChoice===0}" @click="bridgeChoice=0">A. AI is a technology people need to go through.</button><button :class="{selected:bridgeChoice===1}" @click="bridgeChoice=1">B. Students skip organizing and evaluating ideas, gradually depending on generated answers.</button></article></div>
    </div>
    <div v-else-if="step===2" class="diagnosis-result"><span>ROOT CAUSE DIAGNOSIS</span><div class="score-pair"><p><small>标签识别</small><strong>{{recognitionScore}}/3</strong></p><p><small>功能理解</small><strong>{{functionalScore}}/2</strong></p></div><h2 v-if="outcome==='concept'">根因：STEEC 基础概念尚未建立</h2><h2 v-else-if="outcome==='function'">根因：认识结构标签，但不理解每层功能</h2><h2 v-else>根因：理解结构功能，但限时写作应用不稳定</h2><p>这篇作文不能简单归因为“缺少结构”。表面上有立场、解释、例子和结论，但核心论点过宽，后续内容没有共同锚点。</p><div class="priority"><span>当前唯一重点</span><b>先修复 T：把“取决于个人”改成明确、可论证的核心主张</b><small>解释、例子和结论暂不同时重写，因为它们都依赖 T。</small></div></div>
    <div v-else-if="step===3" class="prescription"><span>ADAPTIVE PRESCRIPTION</span><h2>{{outcome==='concept'?'从结构识别开始':'从论点功能训练开始'}}</h2><div class="route"><article :class="{active:outcome==='concept'}"><small>01</small><b>STEEC识别</b><p>标签、排序和缺失层判断</p></article><i>→</i><article :class="{active:outcome!=='concept'}"><small>02</small><b>论点辨析</b><p>从宽泛观点中选出可论证的 T</p></article><i>→</i><article><small>03</small><b>解释桥梁</b><p>补全“为什么”与因果链</p></article><i>→</i><article><small>04</small><b>同题提纲重写</b><p>先改结构，不要求立刻重写全文</p></article></div><button @click="unlock(4)">开始 10 分钟结构训练 →</button></div>
    <div v-else class="structure-training"><div class="task-head"><span>10-MIN STRUCTURE PRACTICE</span><h2>本轮只修 T，再检查例子是否真正支撑它</h2><p>不重写整篇作文，也暂时不修改语言错误。</p></div><div class="training-grid"><article><label>01 · 用自己的话重写核心论点 T</label><p class="old-thesis">原句：Whether AI is beneficial depends on individuals.</p><textarea v-model="thesisRewrite" placeholder="请写出一个明确、可论证的英文核心主张……"></textarea><small>目标：明确指出 AI 在教育中造成的具体风险，而不是笼统地说“取决于个人”。</small></article><article><label>02 · 哪个例子最能支撑这个论点？</label><button :class="{selected:evidenceChoice===0}" @click="evidenceChoice=0">A. AI can summarize the key points of a class.</button><button :class="{selected:evidenceChoice===1}" @click="evidenceChoice=1">B. A student asks AI to write an essay and skips organizing and evaluating ideas independently.</button><button :class="{selected:evidenceChoice===2}" @click="evidenceChoice=2">C. People once learned to use telephones and the internet.</button></article></div><div v-if="trainingChecked" :class="['training-result',{passed:trainingPassed}]"><strong>{{trainingPassed?'本轮 T 修复通过':'继续论点微训练'}}</strong><p>{{trainingPassed?'核心论点已经明确，例子也能直接证明“独立思考被削弱”。下一步进入解释桥梁训练，再做同题提纲修复。':'当前论点仍不够明确，或例子不能直接支撑论点。系统不会要求你重写全文，而是继续缩小练习。'}}</p><button v-if="trainingPassed" @click="router.push('/mistake-notebook')">存入 STEEC 学习记忆 →</button></div></div>
    <footer><span>Student B · 真实匿名记录</span><button v-if="step===0" @click="unlock(1)">开始先备检查 →</button><button v-else-if="step===1" :disabled="!allDone" @click="submitted=true;unlock(2)">提交并判断根因 →</button><button v-else-if="step===2" @click="unlock(3)">生成训练处方 →</button><button v-else-if="step===3" @click="unlock(4)">开始专项训练 →</button><button v-else :disabled="!thesisRewrite.trim()||evidenceChoice===null" @click="trainingChecked=true">提交本轮结构训练</button></footer>
  </section>
</main></div></template>

<style scoped>
.demo-app{min-height:100vh;display:grid;grid-template-columns:230px minmax(0,1fr);background:#07110f;color:#effbf6;font-family:Inter,system-ui,sans-serif}.coach-main{padding:0 clamp(22px,4vw,60px) 60px;min-width:0}header{min-height:94px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid rgba(255,255,255,.08)}header>div:first-child span{color:#647b71;font-size:10px;font-weight:800;letter-spacing:.13em}header h1{font-size:25px;margin:5px 0}header>div:last-child{display:flex;gap:7px}header button{border:1px solid #294138;background:transparent;color:#748a81;border-radius:9px;padding:9px 12px;cursor:pointer}header button.active{border-color:#61e1aa;color:#dff7eb}.case-banner{margin:30px 0 22px;padding:30px;border:1px solid rgba(99,226,171,.2);border-radius:18px;background:radial-gradient(circle at 90% 30%,rgba(64,222,154,.13),transparent 25%),#0d1b17;display:flex;align-items:center;justify-content:space-between;gap:30px}.case-banner span,.task-head>span,.diagnosis-result>span,.prescription>span{color:#62e0aa;font-size:10px;font-weight:850;letter-spacing:.13em}.case-banner h2{font-size:30px;margin:9px 0}.case-banner p,.task-head p{color:#789087;margin:0}.case-banner button,.prescription>button,footer button{border:0;background:#67e5af;color:#062218;border-radius:9px;padding:12px 16px;font-weight:850;cursor:pointer;white-space:nowrap}.steps{display:grid;grid-template-columns:repeat(4,1fr);gap:8px;margin-bottom:14px}.steps button{border:0;background:transparent;color:#61776e;display:flex;align-items:center;justify-content:center;gap:8px;padding:10px}.steps i{font-style:normal;width:25px;height:25px;border:1px solid #294138;border-radius:50%;display:grid;place-items:center}.steps button.active{color:#e9f8f1}.steps button.active i,.steps button.done i{background:#5edfa8;color:#062218;border-color:#5edfa8}.work-panel{min-height:570px;border:1px solid rgba(255,255,255,.1);border-radius:18px;background:#0c1915;padding:30px;display:flex;flex-direction:column}.source-grid{display:grid;grid-template-columns:1fr 1fr;gap:22px}.source-grid>article{border:1px solid rgba(255,255,255,.08);border-radius:13px;padding:22px}.source-grid span{color:#61dda8;font-size:10px;letter-spacing:.1em}.source-grid p{font:16px/1.65 Georgia,serif;color:#c5d5ce}.source-grid article>div{padding:12px;background:#091512;margin-top:8px;color:#81978e;line-height:1.55}.source-grid b{display:block;color:#68dfad;margin-bottom:4px}.task-head{text-align:center;margin-bottom:24px}.task-head h2,.diagnosis-result h2,.prescription h2{font-size:28px;margin:9px 0}.label-list{display:grid;gap:9px}.label-list article{display:grid;grid-template-columns:1fr auto;gap:14px;align-items:center;padding:14px;border:1px solid rgba(255,255,255,.08);border-radius:11px}.label-list p{margin:0;color:#c5d5ce;font-family:Georgia,serif}.label-list article>div{display:flex;gap:5px}.label-list button,.function-tests button{border:1px solid #294138;background:#091512;color:#71887e;border-radius:7px;padding:7px 10px;cursor:pointer}.label-list button.selected,.function-tests button.selected{border-color:#5be0a8;color:#e2f8ed;background:rgba(70,219,154,.08)}.function-tests{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-top:14px}.function-tests article{padding:16px;border:1px solid rgba(255,255,255,.08);border-radius:11px;display:flex;flex-direction:column;gap:8px}.function-tests b{font-size:13px}.function-tests button{text-align:left;line-height:1.45}.diagnosis-result,.prescription{text-align:center;max-width:1000px;margin:auto}.score-pair{display:flex;justify-content:center;gap:12px;margin:22px}.score-pair p{min-width:140px;padding:17px;background:#091512;border-radius:12px;display:flex;flex-direction:column;margin:0}.score-pair small{color:#647b71}.score-pair strong{font-size:30px}.diagnosis-result>p{color:#899e95;line-height:1.65}.priority{margin-top:25px;padding:20px;border:1px solid rgba(87,224,168,.28);background:rgba(67,218,153,.07);border-radius:12px;display:flex;flex-direction:column;gap:8px}.priority span{color:#5ddda7;font-size:10px}.priority small{color:#738a80}.route{display:grid;grid-template-columns:1fr auto 1fr auto 1fr auto 1fr;align-items:center;gap:8px;margin:28px 0}.route article{min-height:130px;padding:17px;border:1px solid rgba(255,255,255,.08);border-radius:12px;display:flex;flex-direction:column;text-align:left}.route article.active{border-color:#5de0a8;background:rgba(65,218,151,.08)}.route small{color:#5f766d}.route b{margin:12px 0 6px}.route p{margin:0;color:#6f867c;font-size:11px;line-height:1.5}.route i{color:#58dda6}footer{margin-top:auto;padding-top:22px;border-top:1px solid rgba(255,255,255,.08);display:flex;align-items:center;justify-content:space-between}footer span{color:#5f766d;font-size:11px}footer button:disabled{opacity:.35;cursor:not-allowed}@media(max-width:900px){.demo-app{grid-template-columns:76px minmax(0,1fr)}.source-grid,.function-tests{grid-template-columns:1fr}.route{grid-template-columns:1fr}.route i{transform:rotate(90deg)}}@media(max-width:560px){.demo-app{display:block}.coach-main{padding:0 15px 40px}header{align-items:flex-start;flex-direction:column;padding:18px 0}.case-banner{align-items:flex-start;flex-direction:column}.steps{overflow:auto;grid-template-columns:repeat(4,120px)}.label-list article{grid-template-columns:1fr}.work-panel{padding:18px}}
.steps{grid-template-columns:repeat(5,1fr)}.steps button{cursor:pointer}.steps button.locked{opacity:.4;cursor:not-allowed}
.structure-training{max-width:1000px;width:100%;margin:auto}.training-grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}.training-grid article{padding:20px;border:1px solid rgba(255,255,255,.09);border-radius:13px;background:#091512;display:flex;flex-direction:column;gap:10px}.training-grid label{color:#69e2af;font-size:11px;font-weight:850;letter-spacing:.06em}.old-thesis{color:#dd9f98;font-family:Georgia,serif;line-height:1.5}.training-grid textarea{min-height:145px;resize:vertical;padding:14px;border:1px solid #294138;border-radius:9px;background:#07110f;color:#e6f3ed;line-height:1.6;outline:none}.training-grid textarea:focus{border-color:#5ce0a8}.training-grid small{color:#657b72;line-height:1.5}.training-grid button{padding:11px;border:1px solid #294138;border-radius:8px;background:#07110f;color:#81978d;text-align:left;line-height:1.45;cursor:pointer}.training-grid button.selected{border-color:#5ce0a8;background:rgba(70,220,155,.08);color:#e2f7ed}.training-result{margin-top:16px;padding:17px;border:1px solid rgba(244,143,126,.28);border-radius:12px;background:rgba(244,118,99,.06)}.training-result.passed{border-color:rgba(90,225,170,.3);background:rgba(72,220,158,.07)}.training-result p{color:#81978e;line-height:1.55}.training-result button{border:0;background:transparent;color:#6ce3b1;font-weight:800;cursor:pointer}
@media(max-width:900px){.training-grid{grid-template-columns:1fr}}
